import { useRef, useState } from "react";
import { IconBell, IconFolder, IconSearch } from "../../icons/generated/icons.js";
import { AccountButton, Rail } from "../../shell/index.js";
import { CountBadge } from "../../ui/badge/index.js";
import { Button } from "../../ui/button/index.js";
import { Menu } from "../../ui/menu/index.js";
import { NotificationPopover, type NotificationItem } from "../../ui/notification-list/index.js";
import { sampleNotifications } from "../fixtures/collaboration.js";
import { SectionPage, Specimen } from "../kit.js";

/** A host in miniature: it keeps the rows and applies what the list reports. */
function useNotifications() {
  const [now] = useState(() => Date.now());
  const [items, setItems] = useState<readonly NotificationItem[]>(() => sampleNotifications(now));
  const markRead = (ids: readonly string[], read: boolean) =>
    setItems((rows) => rows.map((row) => (ids.includes(row.id) ? { ...row, read } : row)));
  return {
    now,
    items,
    setItems,
    markRead,
    markAllRead: () => setItems((rows) => rows.map((row) => ({ ...row, read: true }))),
    dismiss: (item: NotificationItem) =>
      setItems((rows) => rows.filter((row) => row.id !== item.id)),
    unread: items.filter((item) => !item.read).length,
  };
}

function InTheShell() {
  const host = useNotifications();
  const [fromAccount, setFromAccount] = useState(false);
  const [fromRail, setFromRail] = useState(false);
  const accountRef = useRef<HTMLButtonElement>(null);
  const railRef = useRef<HTMLButtonElement>(null);
  const list = {
    items: host.items,
    onReadChange: host.markRead,
    onMarkAllRead: host.markAllRead,
    onDismiss: host.dismiss,
    onOpen: () => undefined,
  };
  return (
    <div className="flex w-full flex-wrap items-start gap-8">
      <Menu.Root>
        <Menu.Trigger
          render={
            <AccountButton
              ref={accountRef}
              name="Avery Quinn"
              email="avery.quinn@orbit.example"
              unread={host.unread}
            />
          }
        />
        <Menu.Popup align="end">
          <Menu.Item onClick={() => setFromAccount(true)}>Notifications</Menu.Item>
          <Menu.Item>Profile and preferences</Menu.Item>
          <Menu.Separator />
          <Menu.Item>Sign out</Menu.Item>
        </Menu.Popup>
      </Menu.Root>
      <NotificationPopover
        {...list}
        open={fromAccount}
        onOpenChange={setFromAccount}
        anchor={accountRef}
        finalFocus={accountRef}
      />
      <Rail.Root aria-label="Main (specimen)">
        <Rail.Item icon={<IconFolder />} label="Projects" />
        <Rail.Item icon={<IconSearch />} label="Search" />
        <Rail.Item
          ref={railRef}
          icon={<IconBell />}
          label="Notifications"
          badge={
            host.unread ? (
              <CountBadge value={host.unread} max={99} tone="accent" overlay aria-hidden />
            ) : undefined
          }
          onClick={() => setFromRail((open) => !open)}
        />
      </Rail.Root>
      <NotificationPopover
        {...list}
        open={fromRail}
        onOpenChange={setFromRail}
        anchor={railRef}
        finalFocus={railRef}
        side="inline-end"
        align="end"
      />
    </div>
  );
}

function WithTrigger() {
  const host = useNotifications();
  return (
    <div className="flex">
      <NotificationPopover
        items={host.items}
        onReadChange={host.markRead}
        onMarkAllRead={host.markAllRead}
        onDismiss={host.dismiss}
        trigger={<Button icon={<IconBell />}>Notifications</Button>}
      />
    </div>
  );
}

export default function NotificationListSection() {
  return (
    <SectionPage>
      <Specimen
        title="In a popover"
        description="A fixed box for the shell. The list mounts on opening, so every row shows."
        layout="stack"
        specimenKey="notification-list:default:3"
      >
        <WithTrigger />
      </Specimen>
      <Specimen
        title="With AccountButton and the rail"
        description="The host passes its unread count to each, and opens the popover from a menu item or a rail item. Neither component changes."
        layout="stack"
        wide
        specimenKey="notification-list:default:4"
      >
        <InTheShell />
      </Specimen>
    </SectionPage>
  );
}
